steps.script:
var GS = GameState.state
# Park every unit except the four this scenario needs well off the board so
# nothing else lands in anyone's Engagement Range and muddies the target lists.
var keep = ["U_CUSTODIAN_GUARD_B", "U_BLADE_CHAMPION_A", "U_BOYZ_E", "U_BOYZ_F"]
for uid in GS["units"].keys():
	if uid in keep:
		continue
	var i = 0
	for m in GS["units"][uid]["models"]:
		m["position"] = {"x": 25000.0 + float(i) * 60.0, "y": 25000.0}
		i += 1
# Seat order is incidental to the bug (the reported case was the OTHER
# way round — the opponent's Fight phase, the player's turn to activate);
# P1 active just makes the Custodes the first pick of the 12.04 step.
GS["meta"]["active_player"] = 1
return "parked"

var GS = GameState.state
# 40px = 1". Engagement Range is 2" at 11e.
# Custodian Guard line, locked with Boyz E only.
var guard = GS["units"]["U_CUSTODIAN_GUARD_B"]["models"]
var gx = 1200.0
for i in range(guard.size()):
	guard[i]["alive"] = true
	guard[i]["position"] = {"x": gx + float(i) * 50.0, "y": 700.0}
# The Blade Champion stands 10" behind them, locked with Boyz F only.
GS["units"]["U_BLADE_CHAMPION_A"]["models"][0]["alive"] = true
GS["units"]["U_BLADE_CHAMPION_A"]["models"][0]["position"] = {"x": gx, "y": 1100.0}
# One LIVE Boy from each mob in contact with its own half; the rest stay
# parked. The fixture already has casualties in these mobs, so index 0 is not
# necessarily alive — and a dead model is skipped by every range check.
var placed = []
for pair in [["U_BOYZ_E", 770.0], ["U_BOYZ_F", 1180.0]]:
	var ms = GS["units"][str(pair[0])]["models"]
	for i in range(ms.size()):
		ms[i]["position"] = {"x": 25000.0 + float(i) * 60.0, "y": 25000.0}
	for i in range(ms.size()):
		if ms[i].get("alive", true):
			ms[i]["position"] = {"x": gx, "y": float(pair[1])}
			placed.append("%s#%d" % [str(pair[0]), i])
			break
# Remember how many models each mob still has, so the post-fight step can
# prove BOTH of them actually took hits.
var base = {}
for uid in ["U_BOYZ_E", "U_BOYZ_F"]:
	var n = 0
	for m in GS["units"][uid]["models"]:
		if m.get("alive", true):
			n += 1
	base[uid] = n
Engine.set_meta("scn_alive_baseline", base)
return " ".join(placed)

var fp = PhaseManager.get_current_phase_instance()
var t = fp._get_eligible_melee_targets("U_CUSTODIAN_GUARD_B").keys()
t.sort()
return str(t)

var d = Engine.get_main_loop().root.get_node_or_null("AttackAssignmentDialog")
var out = []
for g in d._groups:
	out.append(str(g.get("owner", "")) + "=" + str(d._component_targets.get(str(g.get("owner", "")), [])))
return " | ".join(out)

var d = Engine.get_main_loop().root.get_node_or_null("AttackAssignmentDialog")
var tl = d.target_list
for i in range(tl.item_count):
	if str(tl.get_item_metadata(i)) == "U_BOYZ_F":
		tl.select(i)
		return str(tl.get_item_metadata(i))
return "not-found"

var d = Engine.get_main_loop().root.get_node_or_null("AttackAssignmentDialog")
var out = []
for a in d.assignments:
	out.append(str(a.get("attacker", "")) + "->" + str(a.get("target", "")))
out.sort()
return " | ".join(out)

var seen = {}
for a in PhaseManager.get_current_phase_instance().confirmed_attacks:
	seen[str(a.get("attacker", "")) + "->" + str(a.get("target", ""))] = true
var keys = seen.keys()
keys.sort()
return " | ".join(keys)

var base = Engine.get_meta("scn_alive_baseline", {})
var out = []
for uid in ["U_BOYZ_E", "U_BOYZ_F"]:
	var n = 0
	for m in GameState.state["units"][uid]["models"]:
		if m.get("alive", true):
			n += 1
	out.append("%s:%s" % [uid, "hit" if n < int(base.get(uid, 0)) else "untouched"])
return " ".join(out)
